703	var current = 0;
704	var slides = document.querySelectorAll('.slide');
705	var total = slides.length;
706	
707	function show(idx) {
708	  slides.forEach(function(s) { s.classList.remove('active'); });
709	  current = (idx + total) % total;
710	  slides[current].classList.add('active');
711	  document.getElementById('pager').textContent = (current + 1) + ' / ' + total;
712	}
713	
714	function next() { show(current + 1); }
715	function prev() { show(current - 1); }
716	
717	document.addEventListener('keydown', function(e) {
718	  if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ') {
719	    e.preventDefault();
720	    next();
721	  } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
722	    e.preventDefault();
723	    prev();
724	  } else if (e.key === 'Home') {
725	    e.preventDefault();
726	    show(0);
727	  } else if (e.key === 'End') {
728	    e.preventDefault();
729	    show(total - 1);
730	  }
731	});
732	
733	// Touch swipe support
734	var touchStartX = 0;
735	document.addEventListener('touchstart', function(e) { touchStartX = e.changedTouches[0].screenX; });
736	document.addEventListener('touchend', function(e) {
737	  var dx = e.changedTouches[0].screenX - touchStartX;
738	  if (Math.abs(dx) > 50) { dx > 0 ? prev() : next(); }
739	});
740	
741	// Reposition keypoints: move each slide's .keypoint right after its h2 (or h1)
742	slides.forEach(function(slide) {
743	  var kp = slide.querySelector('.keypoint');
744	  var heading = slide.querySelector('h2') || slide.querySelector('h1');
745	  if (kp && heading) {
746	    heading.insertAdjacentElement('afterend', kp);
747	  }
748	});
749	
750	show(0);
