456	<script>
457	var current = 0;
458	var slides = document.querySelectorAll('.slide');
459	var total = slides.length;
460	
461	function show(idx) {
462	  slides.forEach(function(s) { s.classList.remove('active'); });
463	  current = (idx + total) % total;
464	  slides[current].classList.add('active');
465	  document.getElementById('pager').textContent = (current + 1) + ' / ' + total;
466	}
467	
468	function next() { show(current + 1); }
469	function prev() { show(current - 1); }
470	
471	document.addEventListener('keydown', function(e) {
472	  if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ') {
473	    e.preventDefault(); next();
474	  } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
475	    e.preventDefault(); prev();
476	  } else if (e.key === 'Home') { e.preventDefault(); show(0); }
477	  else if (e.key === 'End') { e.preventDefault(); show(total - 1); }
478	});
479	
480	// Swipe
481	var touchStartX = 0;
482	document.addEventListener('touchstart', function(e) { touchStartX = e.changedTouches[0].screenX; });
483	document.addEventListener('touchend', function(e) {
484	  var dx = e.changedTouches[0].screenX - touchStartX;
485	  if (Math.abs(dx) > 50) { dx > 0 ? prev() : next(); }
486	});
487	
488	// Move keypoint after h2/h1
489	slides.forEach(function(slide) {
490	  var kp = slide.querySelector('.keypoint');
491	  var heading = slide.querySelector('h2') || slide.querySelector('h1');
492	  if (kp && heading) heading.insertAdjacentElement('afterend', kp);
493	});
